type Issue = { url: string };
type IssueDraft = { title: string; body: string };

article.sections.11.blocks.5.text:
type Agents = {
  github: { createIssue(draft: IssueDraft): Promise<Issue> };
  slack: { sendMessage(text: string): Promise<void> };
};

article.sections.17.blocks.4.text:
```typescript
async function runWorkflow<Input, Partial, Combined, Output>(
  input: Input,
  firstStage: ReadonlyArray<(input: Input) => Promise<Partial>>,
  combine: (parts: Partial[]) => Promise<Combined>,
  secondStage: ReadonlyArray<(result: Combined) => Promise<Output>>,
): Promise<Output[]> {
  const parts = await Promise.all(firstStage.map(task => task(input)));
  const combined = await combine(parts);
  return Promise.all(secondStage.map(task => task(combined)));
}
```

